INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('PPSC Combined Competitive Examination (PMS) 2026 — 48 BS-17 posts (Advertisement 12/2026)', 'Punjab Public Service Commission (PPSC)', 'Punjab, Pakistan', 'government', 'government', 'job', 'open', 'verified', '2026-11-30', 'https://www.ppsc.gop.pk/', 'www.ppsc.gop.pk', 'Punjab domicile; second-division graduation degree from a recognised university, completed on or before 30 November 2026; upper age limit 32 years (raised from 30). 45 Provincial Management Service, 1 Excise & Taxation Officer, 2 Assistant Director Local Fund Audit posts.', 'Punjab domicile; second-division graduation degree from a recognised university, completed on or before 30 November 2026; upper age limit 32 years (raised from 30). 45 Provincial Management Service, 1 Excise & Taxation Officer, 2 Assistant Director Local Fund Audit posts.', 'Open ppsc.gop.pk, find Advertisement No. 12/2026, read the full advertisement and important instructions, then apply online only before midnight on 30 November 2026. Offline applications are not accepted.', 'Rs 1,000 (as listed for Advertisement 12/2026 — confirm the exact fee on ppsc.gop.pk before paying).', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
