INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('FPSC CSS Competitive Examination CE-2027 — Written Examination (online applications CLOSED 25 Nov 2026)', 'Federal Public Service Commission (FPSC)', 'Pakistan (written exam in 19 cities, tentatively from 27 January 2027)', 'government', 'government', 'job', 'closed', 'verified', '2026-11-25', 'https://www.fpsc.gov.pk/', 'www.fpsc.gov.pk', 'Only candidates who qualified the MPT CE-2027 screening test; bachelor''s degree; age, qualification and domicile assessed against the 31 December 2026 cutoff.', 'Only candidates who qualified the MPT CE-2027 screening test; bachelor''s degree; age, qualification and domicile assessed against the 31 December 2026 cutoff.', 'Online applications closed on 25 November 2026. Candidates who applied online in time must still send the signed printed application with supporting documents to FPSC, Aga Khan Road, F-5/1, Islamabad, before 4 December 2026. Check fpsc.gov.pk for the next cycle.', 'Rs 2,200 (paid via PSID before the online deadline).', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Punjab PIU — 13 contract positions, Punjab Nursing and Health Workforce Reform Program (IPL-12001)', 'Program Implementation Unit (PIU), Specialized Healthcare & Medical Education Department, Government of the Punjab', 'Lahore, Punjab', 'government', 'government', 'job', 'open', 'verified', '2026-11-30', 'https://jobs.punjab.gov.pk/', 'jobs.punjab.gov.pk', 'Punjab domicile only; master''s/postgraduate degree for most posts; age below 50/45/40 depending on the post; 13 positions (14 posts — Training Coordinator x2), contract 1–5 years. Read each position on the Punjab Job Portal before applying.', 'Punjab domicile only; master''s/postgraduate degree for most posts; age below 50/45/40 depending on the post; 13 positions (14 posts — Training Coordinator x2), contract 1–5 years. Read each position on the Punjab Job Portal before applying.', 'Apply online at jobs.punjab.gov.pk (search PIU / IPL-12001) AND send attested supporting documents by registered courier to the PIU office, Johar Town, Lahore — both must reach by 5:00 PM on 30 November 2026. Hand-delivered applications are not accepted.', 'No fee stated in the advertisement summary — check the portal listing; courier cost for documents applies.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('NAVTTC PMYSDP Project Posts — PPS-08 to PPS-11 (12 posts, Quetta / Karachi / Hub-Lasbela)', 'National Vocational and Technical Training Commission (NAVTTC)', 'Quetta, Karachi and Hub-Lasbela, Pakistan', 'government', 'government', 'job', 'open', 'verified', '2026-11-30', 'https://jobs.gov.pk/', 'jobs.gov.pk', 'Varies by post — read the full job description for your post on jobs.gov.pk; project posts under the Prime Minister''s Youth Skills Development Program (Balochistan Special Initiative), PPS-08 to PPS-11.', 'Varies by post — read the full job description for your post on jobs.gov.pk; project posts under the Prime Minister''s Youth Skills Development Program (Balochistan Special Initiative), PPS-08 to PPS-11.', 'Open jobs.gov.pk (National Employment Exchange / NEXT), find the NAVTTC PMYSDP vacancies, read the complete job description for your post, then apply online before 30 November 2026. No postal applications.', 'No application fee stated — confirm on jobs.gov.pk before applying.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('National Employment Exchange (NEXT) — live government & overseas jobs portal', 'NAVTTC / Government of Pakistan', 'Pakistan (nationwide + overseas)', 'government', 'government', 'job', 'open', 'verified', NULL, 'https://jobs.gov.pk/', 'jobs.gov.pk', 'Varies by job; to apply you need a verified email, personal details and at least one qualification on your profile. Experience is needed only when the job asks for it.', 'Varies by job; to apply you need a verified email, personal details and at least one qualification on your profile. Experience is needed only when the job asks for it.', 'Register on jobs.gov.pk and verify your email, complete your profile and resume, then search live jobs and apply online. On 26 November 2026 the homepage listed 2,193 government jobs and 86,501 overseas jobs. Helpline: 0800-88866.', 'Free to register and apply.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('HEC Undergraduate Scholarships 2026–27 — Balochistan & Erstwhile FATA (Phase-III, Batch-V, 1,000 scholarships)', 'Higher Education Commission (HEC) Pakistan', 'Pakistan (HEC-recognised universities nationwide)', 'scholarship', 'scholarship', 'scholarship', 'open', 'verified', '2026-12-14', 'https://www.hec.gov.pk/site/bf3', 'www.hec.gov.pk', 'Valid domicile/local certificate of Balochistan or erstwhile FATA (applicant and father); age 22 years or younger on the closing date; 12 years of education (FA/FSc/ICom/ICS/DAE or equivalent) with at least 60% marks. 500 scholarships for Balochistan, 500 for erstwhile FATA; covers tuition/hostel up to Rs 200,000/year plus Rs 12,000/month stipend.', 'Valid domicile/local certificate of Balochistan or erstwhile FATA (applicant and father); age 22 years or younger on the closing date; 12 years of education (FA/FSc/ICom/ICS/DAE or equivalent) with at least 60% marks. 500 scholarships for Balochistan, 500 for erstwhile FATA; covers tuition/hostel up to Rs 200,000/year plus Rs 12,000/month stipend.', 'Apply online only through the HEC scholarship portal via hec.gov.pk/site/bf3 (eportal.hec.gov.pk), upload required documents, pay the test fee via 1Link 1Bill and verify payment on the portal, then submit before 14 December 2026. Hard copies are not required at this stage.', 'Rs 2,000 aptitude test fee, non-refundable, via 1Link 1Bill.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('US–Pakistan Knowledge Corridor PhD Scholarship (USA) — check HEC for current round', 'Higher Education Commission (HEC) Pakistan', 'United States of America', 'scholarship', 'scholarship', 'scholarship', 'unverified', 'unverified', NULL, 'https://www.hec.gov.pk/', 'www.hec.gov.pk', 'PhD applicants to US universities — full eligibility, fields and terms are published on hec.gov.pk; confirm them there before preparing documents.', 'PhD applicants to US universities — full eligibility, fields and terms are published on hec.gov.pk; confirm them there before preparing documents.', 'Check hec.gov.pk for the current Knowledge Corridor round. Rolling applications were reported, with a next stated closing of 30 March for the Fall 2027 session — this date is unconfirmed, so verify it on the official HEC page before applying.', 'No fee stated — check hec.gov.pk.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('DigiSkills 3.0 Batch 05 — 24 free online courses (300,000 seats)', 'DigiSkills Training Program — Ministry of IT & Telecom / Ignite / Virtual University of Pakistan', 'Online (Pakistan)', 'course', 'course', 'course', 'open', 'verified', '2026-11-30', 'https://digiskills.pk/', 'digiskills.pk', 'Open to students, fresh graduates, job seekers and working professionals across Pakistan; CNIC details required at registration; maximum 2 courses per trainee; 12-week courses.', 'Open to students, fresh graduates, job seekers and working professionals across Pakistan; CNIC details required at registration; maximum 2 courses per trainee; 12-week courses.', 'Register only at digiskills.pk/Register.aspx, verify your email, then enrol in up to 2 of the 24 courses. Enrolment is first come, first served and can close early when seats fill — do not wait for the advertised date. Classes begin 1 December 2026.', '100% free at every stage. Never pay anyone promising a guaranteed seat — registration is free.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
