INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('NAVTTC Prime Minister''s Youth Skills Development Program (PMYSDP) — free vocational & high-tech training', 'National Vocational and Technical Training Commission (NAVTTC)', 'Pakistan (866 partner institutes nationwide)', 'course', 'course', 'course', 'unverified', 'unverified', NULL, 'https://navttc.gov.pk/', 'navttc.gov.pk', 'Pakistani citizen aged 18–35 with a valid CNIC or Form-B (per programme rules — confirm the current batch notice on the NSIS portal). Latest batch: 75,000+ trainees across 866 institutes in 103 trades.', 'Pakistani citizen aged 18–35 with a valid CNIC or Form-B (per programme rules — confirm the current batch notice on the NSIS portal). Latest batch: 75,000+ trainees across 866 institutes in 103 trades.', 'Check the NSIS portal (nsis.navttc.gov.pk, linked from navttc.gov.pk) for the next open batch. Batch-III classes started in February 2026 and no next-batch date had been announced as of 26 November 2026. For updates call the NAVTTC helpline 0800-88866 (Mon–Fri, 08:00–16:00).', 'Free training under PMYSDP.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('freeCodeCamp — Free coding certifications (Web Design, JavaScript, Python, Data Science, AI)', 'freeCodeCamp (501(c)(3) nonprofit)', 'Online', 'course', 'course', 'course', 'open', 'verified', NULL, 'https://www.freecodecamp.org/', 'www.freecodecamp.org', 'Open to everyone; no prior experience needed; self-paced. Skills taught include HTML, CSS, JavaScript, Python, Linux, Git, SQL, data science and AI.', 'Open to everyone; no prior experience needed; self-paced. Skills taught include HTML, CSS, JavaScript, Python, Linux, Git, SQL, data science and AI.', 'Create a free account at freecodecamp.org and start at the beginning of the core curriculum. Each free verified certification requires building its 5 certification projects and passing all project tests.', '100% free — courses, projects and certifications.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
