INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Microsoft Learn — Free learning paths (AI, Azure, Copilot and more)', 'Microsoft', 'Online', 'course', 'course', 'course', 'open', 'verified', NULL, 'https://learn.microsoft.com/', 'learn.microsoft.com', 'Open to everyone; free Microsoft account needed to track progress.', 'Open to everyone; free Microsoft account needed to track progress.', 'Open learn.microsoft.com, pick a learning path (e.g. AI, Azure or Copilot essentials), and work through the free modules at your own pace.', 'Free learning content; some applied-skills assessments and certifications are paid — check the individual path page.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Google Skillshop — Free Google Ads & Google Analytics certifications', 'Google', 'Online', 'course', 'course', 'course', 'open', 'verified', NULL, 'https://skillshop.withgoogle.com/', 'skillshop.withgoogle.com', 'Open to everyone; a Google account is needed to sign in.', 'Open to everyone; a Google account is needed to sign in.', 'Sign in at skillshop.withgoogle.com, choose a track such as Google Ads or Google Analytics, complete the e-learning courses and pass the certification assessment.', 'Free training and certification.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Coursera — Free courses to audit (incl. free courses without certificate)', 'Coursera', 'Online', 'course', 'course', 'course', 'open', 'verified', NULL, 'https://www.coursera.org/', 'www.coursera.org', 'Open to everyone; a free Coursera account is needed.', 'Open to everyone; a free Coursera account is needed.', 'Create a free account at coursera.org, open a course and choose the free audit/preview option (many courses let you preview the first module free, including video lessons, readings and graded assignments). Some courses, e.g. Claude Code 101, are free without a certificate.', 'Free to audit / preview the first module of many courses; certificates and full access are paid (Coursera Plus was listed at $239/year on 26 Nov 2026); financial aid is available on many courses — apply on the course page.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Google AI Essentials (Coursera) — beginner AI course (NOT free — paid, financial aid available)', 'Google (via Coursera)', 'Online', 'ai-tools', 'ai-tools', 'course', 'open', 'verified', NULL, 'https://www.coursera.org/', 'www.coursera.org', 'Beginner level, no experience needed; under 5 hours (Google lists under 10 hours for the full specialisation).', 'Beginner level, no experience needed; under 5 hours (Google lists under 10 hours for the full specialisation).', 'Enrol on Coursera and search for Google AI Essentials. Do not treat the 7-day free trial as a free course — it becomes a paid subscription unless cancelled. If you cannot pay, apply for financial aid via the ''Financial aid available'' link on the course page; if approved, you get the course and certificate.', '7-day free trial, then about $20/month in Pakistan ($49/month in the US/Canada) — check the price shown to you; financial aid available.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Upwork — Find freelance work online (guide; no guaranteed income)', 'Upwork', 'Online / Remote (Pakistan)', 'freelancing', 'freelancing', 'guide', 'open', 'verified', NULL, 'https://www.upwork.com/', 'www.upwork.com', 'Open to adults with a marketable skill (e.g. web development, design, writing, data entry, virtual assistance). Pakistani freelancers are active on the platform — the homepage on 26 November 2026 featured a freelancer from Faisalabad, Pakistan.', 'Open to adults with a marketable skill (e.g. web development, design, writing, data entry, virtual assistance). Pakistani freelancers are active on the platform — the homepage on 26 November 2026 featured a freelancer from Faisalabad, Pakistan.', 'Create a freelancer profile with real portfolio samples, apply to posted jobs, and use Upwork''s escrow/milestone payments — release payment only after approved work. Never pay anyone for a ''guaranteed'' job.', 'Free to join; Upwork charges a service fee on freelancer earnings — check the current fee schedule on upwork.com before starting. Income is NOT guaranteed and finding first clients takes time.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
INSERT INTO opportunities (title, company, location, job_type, category, type, status, verification_status, deadline, source_url, source_domain, description, eligibility, procedure, fees, verified_date) VALUES ('Fiverr — Sell freelance services online (guide; no guaranteed income)', 'Fiverr', 'Online / Remote (Pakistan)', 'freelancing', 'freelancing', 'guide', 'open', 'verified', NULL, 'https://www.fiverr.com/', 'www.fiverr.com', 'Open to anyone who can offer a service (design, development, marketing, writing, video, AI services). Freelancers have public profiles with reviews and portfolios.', 'Open to anyone who can offer a service (design, development, marketing, writing, video, AI services). Freelancers have public profiles with reviews and portfolios.', 'Create a free seller account, publish gigs describing exactly what you deliver, message buyers directly, and deliver through Fiverr. Buyer payments are held securely and released only once work is approved or the review period passes; the Resolution Center handles disputes.', 'Free to join and create gigs; Fiverr deducts a commission from completed orders — check the current terms on fiverr.com. Income is NOT guaranteed.', '2026-11-26') ON CONFLICT (title, company) DO NOTHING;
